tests.script:
on Start(unit) {
  let x be missingRule(unit)
}

on Start(units) {
  let x be missingSelect(units)
}

select wounded(_ unit) means unit.hp < unit.maxHp

on Start(unit) {
  let x be unit is wounded
}

rule wounded(_ unit) means unit.hp < unit.maxHp

on Start(unit) {
  let x be wounded(unit, unit)
}

select woundedUnits(_ units) means units[:filter unit where unit.hp < unit.maxHp]

on Start(units) {
  let x be woundedUnits()
}

module DuplicateVariables
on Start {
  let x be 10
  let x be 20
}

module DuplicateParameterVariable
on Start(value) {
  let value be 10
}

module DuplicateBlockVariables
on Start {
  if true {
    let x be 10
    let x be 20
  }
}

module DuplicateHandlerBindArgs
on Start(unit, target, myHandler) {
  publish myHandler(unit: unit, unit: target)
}

module DuplicateHandlerLiteralParams
on Start(unit, target) {
  let shoot as :handler be Shoot(unit, unit)
  publish Done
}
